    reg [18:0] vmstat_d_s1; always @(posedge clk) vmstat_d_s1 <= vmstat_d_s0;
    reg [18:0] vmstat_d_s2; always @(posedge clk) vmstat_d_s2 <= vmstat_d_s1;
